import 'package:flame/game.dart';

import 'asset_manifest.dart';

/// Loads and caches the Skyroot art just like `game js/game/loader.js`.
///
/// The JS loader fetches a `.frames.json` sidecar per sprite sheet so it can
/// slice animations; that sidecar is generated by the original SDK and is not
/// bundled here, so for now we preload the full sheet images and slice them
/// later once the frame data is available.
class GameAssets {
  GameAssets(this.manifest);

  final AssetManifest manifest;
  final Set<String> _loaded = {};

  /// Preload a specific list of manifest keys.
  Future<void> preload(FlameGame game, List<String> keys) async {
    for (final key in keys) {
      if (_loaded.contains(key)) continue;
      await game.images.load(manifest.pathFor(key));
      _loaded.add(key);
    }
  }

  /// Core sheets loaded up front, matching `CORE_SHEETS`/`CORE_SINGLES`
  /// in loader.js plus every remaining key.
  Future<void> preloadAll(FlameGame game) => preload(game, manifest.keys);

  bool isLoaded(String key) => _loaded.contains(key);
}
